import{_ as o,l as d,o as e,c as n,v as r,p as s,x as t,d as l,i as c,S as _}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"加法器与超前进位","description":"","frontmatter":{"title":"加法器与超前进位","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/adder-cla.md","filePath":"cs/adder-cla.md","lastUpdated":1789023840000}'),p={name:"cs/adder-cla.md"};function h(A,a,m,u,C,E){const i=d("Mermaid");return e(),n("div",null,[a[1]||(a[1]=r('<h1 id="加法器与超前进位" tabindex="-1">加法器与超前进位 <a class="header-anchor" href="#加法器与超前进位" aria-label="Permalink to &quot;加法器与超前进位&quot;">​</a></h1><div class="epigraph"><p>一位全加器只看本位与进位入；若进位沿位片行波，延迟与位宽成正比，超前则用生成与传播一次算出各位进位。</p><footer>—— 据 Harris and Harris, Digital Design and Computer Architecture；Patterson and Hennessy, Computer Organization and Design (RISC-V) 整理</footer></div><p>上一课<a href="/cs/decoder-encoder">译码器与编码器</a>钉死了编号与独热的组合块。<a href="/cs/decoder-encoder">进制</a>已要求同权位相加。本课不重讲位权，也不从补码溢出判定再证一遍。缺口是：<strong>加法电路</strong>的结构与延迟——行波太慢，超前进位用生成/传播把进位变成两级组合。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>全加器：\\((c_{i+1},s_i)=\\mathrm{add}(a_i,b_i,c_i)\\)。串 \\(n\\) 位，若 \\(c_{i+1}\\) 等 \\(c_i\\)，则 \\(t_{pd}=\\Theta(n)\\)。字长 32、64 时，这会卡住后课单周期周期。缺口因此不是新的数值定义，而是进位的布尔：生成 \\(g_i=a_i b_i\\)，传播 \\(p_i=a_i+b_i\\)（或 \\(a_i\\oplus b_i\\)），则 \\(c_{i+1}=g_i+p_i c_i\\)，展开成只依赖 \\(a,b\\) 与 \\(c_0\\) 的与或，深度与 \\(n\\) 的关系变成对数级（分组 CLA）或至少远小于 \\(n\\)。</p><p>溢出判定用最高位进位与次高位进位异或，<a href="/cs/twos-complement">补码课</a>已给语义，本课只接线。</p><h3 id="超前不是「异步提前算下一指令」" tabindex="-1">超前不是「异步提前算下一指令」 <a class="header-anchor" href="#超前不是「异步提前算下一指令」" aria-label="Permalink to &quot;超前不是「异步提前算下一指令」&quot;">​</a></h3><p>CLA 仍是同一组合块内部的捷径，没有时钟、没有指令。把 carry-lookahead 理解成流水线超前，名字会污染后课。行波加法器功能与 CLA 相同，只是 \\(t_{pd}\\) 不同。</p><p><span class="marginnote">Harris 用 4 位 CLA 作积木再分层。Patterson/Hennessy 强调 ALU 的加是关键路径候选。本课不把超标量、先行指令执行扯进来。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>1 位全加器两级门。RCA：进位链。CLA：计算全体 \\(g,p\\)，再用组合网络出 \\(c_i\\)。分组：组生成 \\(G\\)、组传播 \\(P\\)，树形连接。减法：\\(\\bar b\\) 加 \\(c_0=1\\)，与补码取负一致。</p>',11)),(e(),s(_,null,{default:t(()=>[c(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20FA%5B%22%E5%85%A8%E5%8A%A0%E5%99%A8%22%5D%20--%3E%20RCA%5B%22%E8%A1%8C%E6%B3%A2%EF%BC%9A%E5%BB%B6%E8%BF%9F%20%CE%98(n)%22%5D%0A%20%20FA%20--%3E%20CLA%5B%22g%2Fp%20%E8%B6%85%E5%89%8D%E8%BF%9B%E4%BD%8D%22%5D%0A%20%20CLA%20--%3E%20ALU%5B%22%E5%90%8E%E8%AF%BE%20ALU%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>后课 ALU 把加减当成这一块，再 MUX 出与或、移位。单周期 CPU 的 <code>add</code> 路径经过寄存器堆、ALU、写回 MUX，加法器深度必须计入。RISC-V 的 <code>add</code> 不因溢出陷入，硬件仍可算出溢出旗标供软件读——本课不强制接异常。进位入 \\(c_0\\) 在减法时为 1，在加法时为 0，只占一位控制，不另铺数据通路。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲超线程、不讲华莱士树乘法。乘法是重复加或后课单独阵列，不在本课。浮点对阶加法是另一通路，位型已在 IEEE 754，电路不在这里画完。</p><p>后课默认：整数加是组合加法器；延迟可用 CLA 降到远小于行波；\\(a-b\\) 用加 \\(\\bar b+1\\)。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>全加器位片；行波进位延迟随 \\(n\\) 线性。</li><li>\\(g,p\\) 把进位变成无链式与或（或对数树）。</li><li>加减同一套；溢出旗标按补码课接线。</li><li>进位入 \\(c_0\\) 区分加与减，不另铺减法器。</li><li>出处：Harris and Harris；Patterson and Hennessy, COD (RISC-V)。</li></ul>',7))])}const B=o(p,[["render",h]]);export{f as __pageData,B as default};
